public class ScopedValueDemo {
    private static final ScopedValue<String> CURRENT_USER = ScopedValue.newInstance();

    public void handleRequest(String userId) {
        ScopedValue.where(CURRENT_USER, userId).run(() -> {
            // The value is immutably bound for the duration of this scope
            processSubTask();
        });
    }

    private void processSubTask() {
        // Safely access the scoped value without passing parameters down the stack
        String user = CURRENT_USER.get();
        System.out.println("Processing request for user: " + user);
    }
}
